from lib import *
S = SS('j245')
steps = [
    step("SynchronousQueue 的容量是 0:remainingCapacity() = 0、size() = 0、isEmpty() = true。没有消费者时 offer(\"a\") 立即返回 false,poll() 与 peek() 返回 null;offer(\"a\", 200 ms) 等了约 209 ms 才返回 false。生产者 put(\"x\") 阻塞 300 ms 期间,size() 仍是 0、peek() 是 null、iterator().hasNext() 是 false,线程状态是 WAITING(已经有一个元素在等,队列里却看不见它);消费者 take() 之后 put 在 320 ms 后返回。已经有消费者在 take() 等待时 offer(\"y\") 返回 true。", t=tl(S(1)), done=lidx(S(1), 'remainingCapacity() = 0', '没有消费者时 offer', 'offer(\"a\", 200 ms)'), mark=lidx(S(1), '生产者已阻塞 300 ms', 'put(\"x\") 在 320 ms 后返回', '已有消费者在 take() 等待时 offer'), kv=KV([['队列自身', '容量 0,size / peek / iterator 永远看不到元素'], ['offer / poll', '没有对方在等就立即失败'], ['put', '阻塞直到有 take(本次 320 ms)']], ['队列自身'])),
    step("Executors.newCachedThreadPool 的队列就是 SynchronousQueue:同时提交 50 个阻塞任务,池里线程数 50、队列元素数 0;任务结束后(等了 300 ms)池里仍有 50 个空闲线程(它的 keepAlive 是 60 秒,这里没有等满)。自己建 ThreadPoolExecutor(2, 4, 1 s, SynchronousQueue):连续提交 10 个阻塞任务,接受 4 个、拒绝 6 个,第 5 个任务就被拒绝(RejectedExecutionException)——没有队列做缓冲,核心线程与最大线程都忙时直接拒绝。", t=tl(S(2)), done=lidx(S(2), '50 个阻塞任务同时提交', '任务结束后空闲线程'), mark=lidx(S(2), 'ThreadPoolExecutor(2, 4, SynchronousQueue)', '第 5 个任务被拒绝'), b=bars([['cached 池线程数', 50, '50'], ['(2, 4) 池接受', 4, '4'], ['(2, 4) 池拒绝', 6, '6']], 50, done=[0, 1, 2]), kv=KV([['newCachedThreadPool', '50 个阻塞任务 → 50 个线程'], ['ThreadPoolExecutor(2, 4, SynchronousQueue)', '10 个任务:接受 4、拒绝 6']], ['ThreadPoolExecutor(2, 4, SynchronousQueue)'])),
    step("公平与非公平:5 个生产者依次(间隔 100 ms)put 并阻塞,然后消费者逐个 take。公平模式(new SynchronousQueue<>(true))按到达顺序取走:[1, 2, 3, 4, 5];默认的非公平模式是栈,后到的先被取走:[5, 4, 3, 2, 1]。排队等待的生产者在默认模式下可能被后来者一直压在下面。", t=tl(S(3)), done=lidx(S(3), 'fair = true'), mark=lidx(S(3), 'fair = false'), kv=KV([['fair = true', '取走顺序 [1, 2, 3, 4, 5]'], ['fair = false(默认)', '取走顺序 [5, 4, 3, 2, 1]']], ['fair = false(默认)'])),
    step("交接成本(1 生产者 + 1 消费者,各传 2,000,000 个对象,5 轮取中位数,不是 JMH):SynchronousQueue 每个对象约 2598 ns,公平版约 2397 ns,ArrayBlockingQueue(1) 约 4976 ns,而容量 1024 的 ArrayBlockingQueue 约 123 ns、LinkedBlockingQueue 约 139 ns。每次传递都要两个线程碰头,多数时候要挂起与唤醒,比有缓冲的队列贵约 20 倍;它换来的是“元素一定已经被另一个线程接走”的语义。", t=tl(S(4)), done=lidx(S(4), 'SynchronousQueue           每个对象', 'SynchronousQueue(fair)'), mark=lidx(S(4), 'ArrayBlockingQueue(1)', 'ArrayBlockingQueue(1024)', 'LinkedBlockingQueue'), b=bars([['SynchronousQueue', 2598, '2598 ns'], ['SynchronousQueue(fair)', 2397, '2397 ns'], ['ArrayBlockingQueue(1)', 4976, '4976 ns'], ['ArrayBlockingQueue(1024)', 123, '123 ns'], ['LinkedBlockingQueue', 139, '139 ns']], 5000, done=[0, 1, 2, 3, 4]), kv=KV([['SynchronousQueue', '约 2.6 µs / 对象'], ['有缓冲的队列', '约 0.12–0.14 µs / 对象']], ['SynchronousQueue'])),
]
A = mkartj('j245', 245, 'Java,并发,SynchronousQueue,线程池,BlockingQueue,公平性,真实验证,动画演示',
    '实测 SynchronousQueue:容量 0,offer 无人等待立即 false,put 阻塞时 size / peek / iterator 都看不到元素;newCachedThreadPool 的 50 个阻塞任务得到 50 个线程,ThreadPoolExecutor(2, 4) 在第 5 个任务拒绝;非公平模式是栈([5, 4, 3, 2, 1]);每个对象交接约 2.6 µs,比有缓冲队列的 0.12–0.14 µs 高约 20 倍。',
    'SynchronousQueue 是最特别的 BlockingQueue:它没有存储。这篇用真实运行量出它的语义、它在线程池里的效果、公平与非公平的取走顺序,以及直接交接的代价。',
    [('0', 'SynchronousQueue 的容量;生产者阻塞时 size()、peek()、iterator() 都看不到元素'), ('4 / 6', 'ThreadPoolExecutor(2, 4, SynchronousQueue) 连续提交 10 个阻塞任务时接受 / 拒绝的数量'), ('2.6 µs vs 0.12 µs', '每个对象的交接成本:SynchronousQueue 与容量 1024 的 ArrayBlockingQueue')],
    [('零容量语义', None), ('线程池里的 SynchronousQueue', None), ('公平与非公平', None), ('交接成本', None)],
    steps, [ENV_J + '。JDK 21.0.12;交接成本是 1 个生产者 + 1 个消费者、2,000,000 个对象、5 轮取中位数的 nanoTime 测量,不是 JMH,数字只用于比较量级', '没有验证:多生产者多消费者下的吞吐、不同 CPU 核数与不同 JDK 的差异(JDK 21 的 SynchronousQueue 实现)、虚拟线程下的行为、ThreadPoolExecutor 的 keepAlive 回收(没有等满 60 秒)'], 'SynchronousQueue')
